package in.tucor.api.buyer;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="buyer_bank_accounts") public class BuyerBankAccount{@Id public UUID id;@Column(name="buyer_id")public UUID buyerId;@Column(name="bank_name")public String bankName;@Column(name="account_type")public String accountType;@Column(name="account_holder_name")public String accountHolderName;@Column(name="account_number")public String accountNumber;public String ifsc;public String branch;public boolean verified;@Column(name="is_primary")public boolean primary;@Column(name="created_at")public Instant createdAt;@PrePersist void create(){if(id==null)id=UUID.randomUUID();if(createdAt==null)createdAt=Instant.now();}}